			function onBtn1Click(e) {
			    var btn1 = e.control;
			    
			    var grdList = app.lookup("grdList");
			    var dsList = app.lookup("dsList");
			    
			    var rowIdx = 2;
			    
			    dsList.getColumnNames().forEach(function(colNm) {
			       
			        // 기본컬럼일경우 추가 제외
			        if (colNm != "DEFULT_COL") {
			            grdList.addColumn({
			                // 1. 추가 컬럼의 width
			                columnLayout: [{
			                    width: "100px"
			                }],
			                // 2. 추가 컬럼의 header정보
			                // - rowIndex는 헤더 컬럼의 로우 인덱스이며 한줄일경우에 0
			                // - colIndex는 0부터 시작 순번컬럼과 기본컬럼이 있으므로 +2부터 시작
			                // - configurator.text는 그리드 헤더에 표현될 label 입니다.
			                header: [{
			                    constraint: {
			                        rowIndex: 0,
			                        colIndex: rowIdx,
			                        colSpan: 1,
			                        rowSpan: 1
			                    },
			                    configurator: function(configurator) {
			                        configurator.text = colNm;
			                    }
			                }],
			                // 3. 추가 컬럼의 detail 정보
			                // - configurator.columnName는 그리드에 바인딩될 데이터 셋의 컬럼명입니다.
			                detail: [{
			                    constraint: {
			                        rowIndex: 0,
			                        colIndex: rowIdx,
			                        colSpan: 1,
			                        rowSpan: 1
			                    },
			                    configurator: function(configurator) {
			                        configurator.columnName = colNm;
			                    }
			                }]
			            });
			            
			            rowIdx++;
			        }
			    });
			    
			}

